module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);
    localparam WALK_LEFT = 1'b0;
    localparam WALK_RIGHT = 1'b1;
    reg state;

    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= WALK_LEFT;
        else if (bump_left || bump_right)
            state <= ~state;
        else
            state <= state;
    end

    assign walk_left  = (state == WALK_LEFT);
