[BEGIN]
module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output walk_left,
    output walk_right
);

    localparam WALK_LEFT  = 1'b0;
    localparam WALK_RIGHT = 1'b1;

    reg state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
        end
        else begin
            case (state)
                WALK_LEFT: begin
                    if (bump_left)
                        state <= WALK_RIGHT;
                    else
                        state <= WALK_LEFT;
                end
                WALK_RIGHT: begin
                    if (bump_right)
                        state <= WALK_LEFT;
                    else
                        state <= WALK_RIGHT;
                end
                default: state <= WALK_LEFT;
            endcase
        end
    end

    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);

endmodule
